-- Dibuat otomatis oleh scripts/seed-sql.mjs dari data/places.json. Jangan diedit manual.
-- Data © OpenStreetMap contributors, ODbL 1.0.

on conflict (id) do update set
  name = excluded.name,
  category = excluded.category,
  lat = excluded.lat,
  lng = excluded.lng,
  address = excluded.address,
  district = excluded.district,
  opening_hours = excluded.opening_hours,
  opening_hours_source = excluded.opening_hours_source,
  opening_hours_url = excluded.opening_hours_url,
  osm_url = excluded.osm_url;
